  '  core. Greys are left alone, so the smoke in a clip keeps its palette colour.',
  '',
].join('\n');
s = s.split(a).join(b + a);
fs.writeFileSync(f, crlf ? s.split('\n').join('\r\n') : s); console.log('README updated');
EOF
